/* Quantum Rose Theme — Tailwind v3 (rgb) */
/* Channel triplets — consume via rgb(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* Quantum Rose Theme - Auto-generated from tweakcn */

  /* Light mode (:root) */
  :root {
    --background: 255 240 248;
    --foreground: 146 18 91;
    --card: 253 246 251;
    --card-foreground: 146 18 91;
    --popover: 253 246 251;
    --popover-foreground: 146 18 91;
    --primary: 229 10 122;
    --primary-foreground: 255 255 255;
    --secondary: 254 213 254;
    --secondary-foreground: 146 18 91;
    --muted: 255 226 241;
    --muted-foreground: 190 66 130;
    --accent: 255 195 228;
    --accent-foreground: 146 18 91;
    --destructive: 207 56 104;
    --destructive-foreground: 255 255 255;
    --border: 253 201 230;
    --input: 254 213 254;
    --ring: 229 10 122;
    --chart-1: 229 10 122;
    --chart-2: 195 78 151;
    --chart-3: 152 106 180;
    --chart-4: 114 111 191;
    --chart-5: 95 133 255;
    --radius: 0.5rem;
    --sidebar: 253 237 245;
    --sidebar-foreground: 146 18 91;
    --sidebar-primary: 229 10 122;
    --sidebar-primary-foreground: 255 255 255;
    --sidebar-accent: 255 195 228;
    --sidebar-accent-foreground: 146 18 91;
    --sidebar-border: 252 222 239;
    --sidebar-ring: 229 10 122;
    --font-sans: Poppins, sans-serif;
    --font-serif: Playfair Display, serif;
    --font-mono: Space Mono, monospace;
    --shadow-color: 130 23 77;
    --shadow-opacity: 0.18;
    --shadow-blur: 0px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0px;
    --shadow-offset-y: 3px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0px 3px 0px 0px hsl(330 70% 30% / 0.09);
    --shadow-xs: 0px 3px 0px 0px hsl(330 70% 30% / 0.09);
    --shadow-sm:
      0px 3px 0px 0px hsl(330 70% 30% / 0.18),
      0px 1px 2px -1px hsl(330 70% 30% / 0.18);
    --shadow:
      0px 3px 0px 0px hsl(330 70% 30% / 0.18),
      0px 1px 2px -1px hsl(330 70% 30% / 0.18);
    --shadow-md:
      0px 3px 0px 0px hsl(330 70% 30% / 0.18),
      0px 2px 4px -1px hsl(330 70% 30% / 0.18);
    --shadow-lg:
      0px 3px 0px 0px hsl(330 70% 30% / 0.18),
      0px 4px 6px -1px hsl(330 70% 30% / 0.18);
    --shadow-xl:
      0px 3px 0px 0px hsl(330 70% 30% / 0.18),
      0px 8px 10px -1px hsl(330 70% 30% / 0.18);
    --shadow-2xl: 0px 3px 0px 0px hsl(330 70% 30% / 0.45);
    --tracking-normal: 0em;
  }

  /* Dark mode (.dark) */
  .dark {
    --background: 25 10 33;
    --foreground: 254 178 254;
    --card: 43 19 54;
    --card-foreground: 254 178 254;
    --popover: 43 19 54;
    --popover-foreground: 254 178 254;
    --primary: 253 106 237;
    --primary-foreground: 24 5 24;
    --secondary: 70 33 79;
    --secondary-foreground: 254 178 254;
    --muted: 51 24 66;
    --muted-foreground: 213 122 213;
    --accent: 91 32 94;
    --accent-foreground: 254 178 254;
    --destructive: 252 43 117;
    --destructive-foreground: 248 248 248;
    --border: 75 28 96;
    --input: 70 33 79;
    --ring: 253 106 237;
    --chart-1: 253 106 237;
    --chart-2: 196 87 228;
    --chart-3: 143 96 252;
    --chart-4: 112 117 224;
    --chart-5: 83 121 253;
    --radius: 0.5rem;
    --sidebar: 27 12 36;
    --sidebar-foreground: 254 178 254;
    --sidebar-primary: 253 106 237;
    --sidebar-primary-foreground: 24 5 24;
    --sidebar-accent: 91 32 94;
    --sidebar-accent-foreground: 254 178 254;
    --sidebar-border: 75 28 96;
    --sidebar-ring: 253 106 237;
    --font-sans: Quicksand, sans-serif;
    --font-serif: Playfair Display, serif;
    --font-mono: Space Mono, monospace;
    --shadow-color: 229 26 230;
    --shadow-opacity: 0.18;
    --shadow-blur: 0px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0px;
    --shadow-offset-y: 3px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0px 3px 0px 0px hsl(300 80% 50% / 0.09);
    --shadow-xs: 0px 3px 0px 0px hsl(300 80% 50% / 0.09);
    --shadow-sm:
      0px 3px 0px 0px hsl(300 80% 50% / 0.18),
      0px 1px 2px -1px hsl(300 80% 50% / 0.18);
    --shadow:
      0px 3px 0px 0px hsl(300 80% 50% / 0.18),
      0px 1px 2px -1px hsl(300 80% 50% / 0.18);
    --shadow-md:
      0px 3px 0px 0px hsl(300 80% 50% / 0.18),
      0px 2px 4px -1px hsl(300 80% 50% / 0.18);
    --shadow-lg:
      0px 3px 0px 0px hsl(300 80% 50% / 0.18),
      0px 4px 6px -1px hsl(300 80% 50% / 0.18);
    --shadow-xl:
      0px 3px 0px 0px hsl(300 80% 50% / 0.18),
      0px 8px 10px -1px hsl(300 80% 50% / 0.18);
    --shadow-2xl: 0px 3px 0px 0px hsl(300 80% 50% / 0.45);
  }

}
